class Solution:
    def evalPostfix(self, tokens: List[str]) -> int:
        t = list(tokens)
        while len(t) > 1:
            i = next(k for k, x in enumerate(t) if x in ("+", "-", "*", "/"))
            a, b, op = int(t[i - 2]), int(t[i - 1]), t[i]
            if op == "+": r = a + b
            elif op == "-": r = a - b
            elif op == "*": r = a * b
            else: r = abs(a) // abs(b) * (1 if (a < 0) == (b < 0) else -1)
            t[i - 2:i + 1] = [str(r)]
        return int(t[0])

