class Solution {
    public int evalPostfix(String[] tokens) {
        List<String> t = new ArrayList<>(Arrays.asList(tokens));
        while (t.size() > 1) {
            int i = 0;
            while (!"+-*/".contains(t.get(i)) || t.get(i).length() != 1) i++;
            int a = Integer.parseInt(t.get(i - 2)), b = Integer.parseInt(t.get(i - 1));
            String op = t.get(i);
            int r = op.equals("+") ? a + b : op.equals("-") ? a - b : op.equals("*") ? a * b : a / b;
            t.subList(i - 2, i + 1).clear();
            t.add(i - 2, String.valueOf(r));
        }
        return Integer.parseInt(t.get(0));
    }
}

