class Solution {
public:
    int evalPostfix(vector<string>& tokens) {
        vector<string> t = tokens;
        auto isOp = [](const string& x) { return x.size() == 1 && string("+-*/").find(x[0]) != string::npos; };
        while (t.size() > 1) {
            size_t i = 0;
            while (!isOp(t[i])) i++;
            int a = stoi(t[i - 2]), b = stoi(t[i - 1]);
            char op = t[i][0];
            int r = op == '+' ? a + b : op == '-' ? a - b : op == '*' ? a * b : a / b;
            t.erase(t.begin() + i - 2, t.begin() + i + 1);
            t.insert(t.begin() + i - 2, to_string(r));
        }
        return stoi(t[0]);
    }
};

