static bool isOp(const char* x) {
    return x[1] == '\0' && (x[0] == '+' || x[0] == '-' || x[0] == '*' || x[0] == '/');
}

int evalPostfix(char** tokens, int tokensSize) {
    int n = tokensSize;
    int* val = malloc(n * sizeof(int));
    char* op = malloc(n);
    for (int i = 0; i < n; i++) {
        op[i] = isOp(tokens[i]) ? tokens[i][0] : 0;
        val[i] = op[i] ? 0 : atoi(tokens[i]);
    }
    while (n > 1) {
        int i = 0;
        while (!op[i]) i++;
        int a = val[i - 2], b = val[i - 1];
        int r = op[i] == '+' ? a + b : op[i] == '-' ? a - b : op[i] == '*' ? a * b : a / b;
        val[i - 2] = r;
        op[i - 2] = 0;
        memmove(val + i - 1, val + i + 1, (n - i - 1) * sizeof(int));
        memmove(op + i - 1, op + i + 1, n - i - 1);
        n -= 2;
    }
    int answer = val[0];
    free(val);
    free(op);
    return answer;
}

