class Solution:
    def evalPostfix(self, tokens: List[str]) -> int:
        stack = []
        for t in tokens:
            if t in ("+", "-", "*", "/"):
                b, a = stack.pop(), stack.pop()
                if t == "+": stack.append(a + b)
                elif t == "-": stack.append(a - b)
                elif t == "*": stack.append(a * b)
                else: stack.append(abs(a) // abs(b) * (1 if (a < 0) == (b < 0) else -1))
            else:
                stack.append(int(t))
        return stack[0]

